def normalize(tokens, lexicon):
    return [lexicon.get(t.lower(), t.lower()) for t in tokens]

def score(tokens, polarity):
    total = 0.0
    for t in tokens:
        total += polarity.get(t, 0.0)
    return total / max(len(tokens), 1)

const negators = new Set(["not", "si", "never"])

export function contextualPolarity(tokens: string[], base: number): number {
  const hasNegator = tokens.some(t => negators.has(t.toLowerCase()))
  if (hasNegator) return -base * 0.8
  return base
}
